import * as THREE from 'three/webgpu';
import { attribute } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const colors = {
    background: 0x0b0b10,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  const fieldCount = 1110;
  const coreCount = 90;

  // Generate field particle positions on ellipsoidal shell
  const ellipsoidRadii = { x: 3, y: 2, z: 2.5 };
  const ellipsoidCenter = { x: 0, y: 0, z: -1.5 };

  const fieldPositions = new Float32Array(fieldCount * 3);
  const fieldOpacities = new Float32Array(fieldCount);
  const fieldOriginalPositions = new Float32Array(fieldCount * 3);

  for (let i = 0; i < fieldCount; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI * 2;

    const sx = Math.sin(theta) * Math.cos(phi);
    const sy = Math.sin(theta) * Math.sin(phi);
    const sz = Math.cos(theta);

    const px = sx * ellipsoidRadii.x + ellipsoidCenter.x;
    const py = sy * ellipsoidRadii.y + ellipsoidCenter.y;
    const pz = sz * ellipsoidRadii.z + ellipsoidCenter.z;

    fieldPositions[i * 3] = px;
    fieldPositions[i * 3 + 1] = py;
    fieldPositions[i * 3 + 2] = pz;
    fieldOriginalPositions[i * 3] = px;
    fieldOriginalPositions[i * 3 + 1] = py;
    fieldOriginalPositions[i * 3 + 2] = pz;

    // Depth falloff: linear from 0.9 at z=0 to 0.15 at z=-5
    const opacity = 0.9 - (pz / -5) * 0.75;
    fieldOpacities[i] = Math.max(0.15, Math.min(0.9, opacity));
  }

  // Generate core particle positions
  const corePositions = new Float32Array(coreCount * 3);
  const coreOriginalPositions = new Float32Array(coreCount * 3);

  for (let i = 0; i < coreCount; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI * 2;
    const r = Math.random() * 0.5;

    const px = r * Math.sin(theta) * Math.cos(phi);
    const py = r * Math.sin(theta) * Math.sin(phi);
    const pz = r * Math.cos(theta);

    corePositions[i * 3] = px;
    corePositions[i * 3 + 1] = py;
    corePositions[i * 3 + 2] = pz;
    coreOriginalPositions[i * 3] = px;
    coreOriginalPositions[i * 3 + 1] = py;
    coreOriginalPositions[i * 3 + 2] = pz;
  }

  // Field particles geometry
  const icosaGeometry = new THREE.IcosahedronGeometry(0.012, 0);
  const fieldGeometry = new THREE.InstancedBufferGeometry();
  fieldGeometry.copy(icosaGeometry);
  fieldGeometry.instanceCount = fieldCount;
  fieldGeometry.setAttribute('instancePosition', new THREE.InstancedBufferAttribute(fieldPositions, 3));
  fieldGeometry.setAttribute('instanceOpacity', new THREE.InstancedBufferAttribute(fieldOpacities, 1));

  const positionGeom = attribute('position', 'vec3');
  const positionInst = attribute('instancePosition', 'vec3');
  const opacityInst = attribute('instanceOpacity', 'float');

  const fieldMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(colors.paper),
    metalness: 0,
    roughness: 1,
    emissive: new THREE.Color(colors.paper),
    emissiveIntensity: 0.9,
    transparent: true,
    side: THREE.DoubleSide,
  });

  fieldMaterial.positionNode = positionGeom.add(positionInst);
  fieldMaterial.opacityNode = opacityInst;

  const fieldMesh = new THREE.Mesh(fieldGeometry, fieldMaterial);
  group.add(fieldMesh);

  // Core particles geometry
  const coreGeometry = new THREE.InstancedBufferGeometry();
  coreGeometry.copy(icosaGeometry);
  coreGeometry.instanceCount = coreCount;
  coreGeometry.setAttribute('instancePosition', new THREE.InstancedBufferAttribute(corePositions, 3));

  const corePositionInst = attribute('instancePosition', 'vec3');

  const coreMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    metalness: 0,
    roughness: 0.5,
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.8,
    transparent: true,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
  });

  coreMaterial.positionNode = positionGeom.add(corePositionInst);
  coreMaterial.opacityNode = attribute('opacity', 'float');

  const coreMesh = new THREE.Mesh(coreGeometry, coreMaterial);
  group.add(coreMesh);

  // Text meshes
  const heroText = ctx.fontAtlas.createTextMesh('NOVA ATELIER', {
    font: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    color: colors.paper,
    align: 'center',
    baseline: 'middle',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createTextMesh('Precision instruments for the dark hours.', {
    font: 'JetBrains Mono',
    fontSize: 40,
    fontWeight: 400,
    letterSpacing: 0.02,
    color: colors.paper,
    align: 'center',
    baseline: 'middle',
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createTextMesh('EST. 2019 / GENEVA AND KYOTO', {
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    color: colors.paper,
    align: 'center',
    baseline: 'middle',
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // Animation state
  const tweens = [];
  const animState = { coreEmissive: 1.8 };

  // Core emissive pulse: 1.5 to 1.8 sine at 0.1 Hz (10 second period)
  const pulseTl = gsap.timeline({ repeat: -1 })
    .to(animState, {
      coreEmissive: 1.5,
      duration: 5,
      ease: 'sine.inOut',
      onUpdate: () => {
        coreMaterial.emissiveIntensity = animState.coreEmissive;
      },
    })
    .to(animState, {
      coreEmissive: 1.8,
      duration: 5,
      ease: 'sine.inOut',
      onUpdate: () => {
        coreMaterial.emissiveIntensity = animState.coreEmissive;
      },
    });
  tweens.push(pulseTl);

  // Ambient drift: each particle orbits its anchor ±0.04 units at 0.05 Hz (20 second period)
  for (let i = 0; i < fieldCount; i++) {
    const phase = Math.random() * Math.PI * 2;
    const ox = fieldOriginalPositions[i * 3];
    const oy = fieldOriginalPositions[i * 3 + 1];

    const state = { t: phase };
    const tw = gsap.to(state, {
      t: phase + Math.PI * 2,
      duration: 20,
      repeat: -1,
      ease: 'none',
      onUpdate: () => {
        const t = state.t;
        fieldPositions[i * 3] = ox + Math.cos(t) * 0.04;
        fieldPositions[i * 3 + 1] = oy + Math.sin(t) * 0.04;
        fieldGeometry.attributes.instancePosition.needsUpdate = true;
      },
    });
    tweens.push(tw);
  }

  for (let i = 0; i < coreCount; i++) {
    const phase = Math.random() * Math.PI * 2;
    const ox = coreOriginalPositions[i * 3];
    const oy = coreOriginalPositions[i * 3 + 1];

    const state = { t: phase };
    const tw = gsap.to(state, {
      t: phase + Math.PI * 2,
      duration: 20,
      repeat: -1,
      ease: 'none',
      onUpdate: () => {
        const t = state.t;
        corePositions[i * 3] = ox + Math.cos(t) * 0.04;
        corePositions[i * 3 + 1] = oy + Math.sin(t) * 0.04;
        coreGeometry.attributes.instancePosition.needsUpdate = true;
      },
    });
    tweens.push(tw);
  }

  // Apply particle-emerge primitive
  if (ctx.primitives && ctx.primitives['particle-emerge']) {
    ctx.primitives['particle-emerge'](group, {
      count: 1200,
      durationMs: 1400,
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    tweens.forEach(t => t && t.kill && t.kill());
    gsap.killTweensOf(animState);

    fieldGeometry.dispose();
    coreGeometry.dispose();
    icosaGeometry.dispose();
    fieldMaterial.dispose();
    coreMaterial.dispose();
  };

  group.userData.handlers = {};

  return group;
}
